import {
  Group,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // ── Text content extraction ──────────────────────────────────────────────
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  const headlineItem = items.find((item) => item.role === 'headline');
  const textContent = headlineItem ? headlineItem.text : 'Collection';
  const fontSize = headlineItem?.typography?.fontSize ?? 96;

  // ── Background plane ─────────────────────────────────────────────────────
  const planeWidth = 3.6;
  const planeHeight = 0.9;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // surface fallback
    transparent: true,
  });
  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Load texture once available
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ── Text overlay ─────────────────────────────────────────────────────────
  const textObj = ctx.fontAtlas.createText(textContent, {
    fontSize: fontSize,
    color: '#e8ecf2',
    align: 'center',
  });
  textObj.position.z = 0.01; // avoid z-fighting
  group.add(textObj);

  // ── Event handlers (none) ────────────────────────────────────────────────
  group.userData.handlers = {};

  // ── Cleanup ──────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();

    textObj.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        const mat = child.material;
        if (Array.isArray(mat)) {
          mat.forEach((m) => m.dispose());
        } else {
          mat.dispose();
        }
      }
    });
  };

  return group;
}
